use aes_gcm::{Aes256Gcm, KeyInit, Nonce, aead::Aead};
use tokio::sync::{Mutex, mpsc};
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

// Load the 32-byte AES key from a secure runtime source instead of hard-coding it.
// The key material must never be embedded in the binary/source.
fn load_aes_key() -> [u8; 32] {
    let key_hex = std::env::var("AES_KEY_HEX")
        .expect("AES_KEY_HEX environment variable must be set with a 64-char hex key");
    let bytes = hex_decode(&key_hex).expect("AES_KEY_HEX must be valid hex");
    let key: [u8; 32] = bytes
        .as_slice()
        .try_into()
        .expect("AES key must be exactly 32 bytes");
    key
}

// Minimal hex decoder to avoid adding an external dependency.
fn hex_decode(s: &str) -> Result<Vec<u8>, &'static str> {
    if s.len() % 2 != 0 {
        return Err("hex string must have even length");
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let bytes = s.as_bytes();
    let val = |c: u8| -> Result<u8, &'static str> {
        match c {
            b'0'..=b'9' => Ok(c - b'0'),
            b'a'..=b'f' => Ok(c - b'a' + 10),
            b'A'..=b'F' => Ok(c - b'A' + 10),
            _ => Err("invalid hex character"),
        }
    };
    let mut i = 0;
    while i < bytes.len() {
        let hi = val(bytes[i])?;
        let lo = val(bytes[i + 1])?;
        out.push((hi << 4) | lo);
        i += 2;
    }
    Ok(out)
}

struct NonceState {
    counter: u64,
    epoch_offset: u64,
}

impl NonceState {
    fn new() -> Self {
        let epoch_offset = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        NonceState {
            counter: 0,
            epoch_offset,
        }
    }

    fn next_nonce(&mut self) -> [u8; 12] {
        let mut nonce_bytes = [0u8; 12];
        // Pack epoch_offset into first 4 bytes and counter into last 8
        let epoch_truncated = (self.epoch_offset & 0xFFFFFFFF) as u32;
        nonce_bytes[0..4].copy_from_slice(&epoch_truncated.to_le_bytes());
        nonce_bytes[4..12].copy_from_slice(&self.counter.to_le_bytes());
        self.counter = self.counter.wrapping_add(1);
        nonce_bytes
    }
}

struct EncryptedLogger {
    cipher: Aes256Gcm,
    nonce_state: Arc<Mutex<NonceState>>,
    tx: mpsc::Sender<Vec<u8>>,
}

impl EncryptedLogger {
    fn new(tx: mpsc::Sender<Vec<u8>>) -> Self {
        let key = load_aes_key();
        let cipher = Aes256Gcm::new_from_slice(&key).unwrap();
        EncryptedLogger {
            cipher,
            nonce_state: Arc::new(Mutex::new(NonceState::new())),
            tx,
        }
    }

    async fn encrypt_and_send(&self, message: &[u8]) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        let nonce_bytes = self.derive_nonce_for_message(message).await;
        let nonce = Nonce::from_slice(&nonce_bytes);
        let ciphertext = self.cipher.encrypt(nonce, message)?;

        let mut payload = Vec::with_capacity(12 + ciphertext.len());
        payload.extend_from_slice(&nonce_bytes);
        payload.extend_from_slice(&ciphertext);
        self.tx.send(payload).await?;
        Ok(())
    }

    async fn derive_nonce_for_message(&self, _message: &[u8]) -> [u8; 12] {
        // Acquire lock, compute nonce, and increment atomically
        let mut state = self.nonce_state.lock().await;
        let mut nonce_bytes = [0u8; 12];
        let epoch_truncated = (state.epoch_offset & 0xFFFFFFFF) as u32;
        nonce_bytes[0..4].copy_from_slice(&epoch_truncated.to_le_bytes());
        nonce_bytes[4..12].copy_from_slice(&state.counter.to_le_bytes());
        // Increment counter while still holding the lock
        state.counter = state.counter.wrapping_add(1);
        drop(state);

        nonce_bytes
    }
}

struct MonitoringAgent {
    logger: Arc<EncryptedLogger>,
}

impl MonitoringAgent {
    fn new(tx: mpsc::Sender<Vec<u8>>) -> Self {
        MonitoringAgent {
            logger: Arc::new(EncryptedLogger::new(tx)),
        }
    }

    async fn log_event(&self, event: &str) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
        self.logger.encrypt_and_send(event.as_bytes()).await
    }

    async fn run_concurrent_logging(&self) {
        let mut handles = vec![];
        for i in 0..10 {
            let logger = self.logger.clone();
            let handle = tokio::spawn(async move {
                let msg = format!("Event {}: system health check", i);
                logger.encrypt_and_send(msg.as_bytes()).await.unwrap();
            });
            handles.push(handle);
        }
        for h in handles {
            h.await.unwrap();
        }
    }
}

#[tokio::main]
async fn main() {
    let (tx, mut rx) = mpsc::channel(100);
    let agent = MonitoringAgent::new(tx);

    tokio::spawn(async move {
        while let Some(payload) = rx.recv().await {
            // In production: forward to log aggregator
            println!("Encrypted payload: {} bytes", payload.len());
        }
    });

    agent.log_event("Agent started").await.unwrap();
    agent.run_concurrent_logging().await;
    agent.log_event("Agent stopping").await.unwrap();
}
